/** The seven Claude Code lifecycle events Minsky's guards currently hook. */
export type LifecycleEvent =
  | "PreToolUse"
  | "PostToolUse"
  | "UserPromptSubmit"
  | "SessionStart"
  | "Stop"
  | "SubagentStop"
  | "SessionEnd";

