/**
 * A guard's outcome for a single dispatch. `null`/`undefined`/`void` means
 * "no output" — the guard neither denies nor wants to contribute context
 * (the historical "exit 0, write nothing" allow path every guard already
 * implements).
 */
export interface GuardOutcome {
  /**
   * Set to deny the tool call. Only honored when the guard's registration
   * has `denyCapable: true` — the dispatcher short-circuits the remaining
   * guards on the first denial (D1's first-deny-wins ordering, now an
   * explicit registry-order property instead of an implicit settings.json
   * array-position accident).
   */
  deny?: { reason: string };
  /**
   * Set to contribute an `additionalContext` fragment. The dispatcher
   * concatenates every matched guard's fragment (registry order, one
   * paragraph per guard) into a single consolidated `HookOutput` (D1).
   */
  additionalContext?: string;
  /**
   * Raw non-JSON line(s) the guard wants written verbatim to STDERR — e.g.
   * its own legacy per-guard override audit line (the "legacy vars remain
   * honored by the guards themselves" carve-out; deprecation-shim removal is
   * Phase 7, not this task). Each string should include its own trailing
   * newline.
   *
   * STDERR, not stdout (mt#3625). These went to stdout until the dispatch's
   * JSON was found to be discarded wholesale by Claude Code whenever stdout
   * carried anything else — so an audit line could silently void a later
   * guard's deny on the same call.
   *
   * That behavior is reproducible on demand: `bun
   * scripts/run-dispatcher-scenario.ts --scenario override-deny-precedence`
   * (mt#3756). It is deliberately NOT a unit test — `dispatcher.test.ts`
   * injects `recordFireLogFn`/`resolveDispatchContextFn`, so it cannot observe
   * the real write path this bug lived on, which is why the original
   * measurement was taken against the live dispatcher and left 19 fixture
   * records in the production fire-log.
   */
  auditLines?: string[];
  /**
   * Optional calibration record to log via `logCalibrationRecord` (D4).
   * Requires the guard's registration to declare a `calibrationLog` name;
   * silently ignored otherwise.
   */
  calibration?: Record<string, unknown>;
  /**
   * UserPromptSubmit-only: sets the session's display title. Added for
   * `auto-session-title.ts` (ADR-028 Phase 2b, mt#2687) — the one guard in
   * the family whose output is a scalar session label rather than additive
   * `additionalContext`. Unlike `additionalContext` (concatenated across
   * every matched guard), `sessionTitle` is last-write-wins across the
   * matched set — in practice only one guard in any registered family sets
   * it, so ordering is moot.
   */
  sessionTitle?: string;
  /**
   * PreToolUse-only: replaces the tool's ARGUMENTS before it runs, forwarded
   * verbatim as `hookSpecificOutput.updatedInput` (mt#3612). A third output
   * shape alongside `deny` (short-circuit) and `additionalContext`
   * (concatenate) — it is a REPLACEMENT value, so neither of those rules
   * applies to it.
   *
   * Aggregation: **first guard in registry order wins.** A later guard's
   * rewrite is DISCARDED and the discard is written as a stderr audit line
   * naming both guards (stderr because Claude Code drops a PreToolUse hook's
   * whole output if stdout holds anything but the one JSON object). Registry order is ADR-028 D1's explicit declared ordering
   * property (the same one first-deny-wins rests on) — deliberately NOT the
   * last-write-wins that `sessionTitle` above uses, because that rule is
   * documented as moot for a single-writer field and a silently dropped
   * argument rewrite is a correctness failure rather than a cosmetic one.
   *
   * A guard returning both `deny` and `updatedInput` gets the deny: the tool
   * never runs, so its arguments are irrelevant.
   *
   * Claude Code honors the field on PreToolUse only. The dispatcher forwards
   * it on whatever event the guard is registered for — same as `sessionTitle`
   * above, which is documented UserPromptSubmit-only and likewise forwarded
   * unconditionally. Scoping is the harness's; the dispatcher does not silently
   * drop a value a guard deliberately returned.
   */
  updatedInput?: Record<string, unknown>;
}

export type GuardRunResult = GuardOutcome | null | undefined | void;

/**
 * The pure-function contract every dispatcher-migrated guard module exports.
 *
 * Phase 2a generalization (mt#2652): `run`'s input parameter is typed as the
 * BASE `ClaudeHookInput` — the fields every lifecycle event's payload
 * carries (`session_id`, `transcript_path`, `cwd`, `hook_event_name`,
 * `agent_id`). Tool-scoped guards (PreToolUse/PostToolUse) declare their own
 * `run(input: ToolHookInput, ctx)` — a narrower parameter type than the
 * interface's `ClaudeHookInput` — which is permitted because this member is
 * declared with METHOD SHORTHAND syntax (`run(...)`, not `run: (...) => ...`
 * as a property), and TypeScript checks method parameters bivariantly. That
 * lets a single `GuardModule` contract cover both tool-scoped guards
 * (`ToolHookInput`, a `ClaudeHookInput` subtype — e.g.
 * `check-guessed-session-path.ts`) and non-tool-scoped guards
 * (`ClaudeHookInput` exactly — e.g. the UserPromptSubmit guidance-detector
 * family migrated in this phase) without a union type or per-event generic
 * parameter. Phase 1's deferred-generalization note (superseded by this
 * comment) predicted exactly this: "will need to generalize... when that
 * phase lands."
 */
export interface GuardModule {
  run(input: ClaudeHookInput, ctx: DispatchContext): GuardRunResult | Promise<GuardRunResult>;
}

// ---------------------------------------------------------------------------
// Registration schema (D2)
// ---------------------------------------------------------------------------

/**
 * Declarative registration for one guard (ADR-028 D2). The registry is the
 * single source of truth for event, matcher, timeout, and calibration
 * wiring — replacing the copy-pasted `.claude/settings.json` matcher strings
 * (e.g. the literal string `"Edit|Write|NotebookEdit"` appearing verbatim in
 * three separate `PreToolUse` blocks today).
 */
export interface GuardRegistration {
  /** Guard name — also the `MINSKY_HOOK_OVERRIDE` key (D3) and the default calibration-log discriminator. */
  name: string;
  /** Which dispatcher loads this guard. */
  event: LifecycleEvent;
  /**
   * Tool-name regex (PreToolUse/PostToolUse only), tested against
   * `tool_name` via `new RegExp(matcher).test(...)`. Omit for
   * non-tool-scoped events (`UserPromptSubmit`, `SessionStart`, `Stop`,
   * `SubagentStop`, `SessionEnd`) — those always match once the event
   * matches, mirroring today's `matcher`-less settings.json blocks.
   */
  matcher?: string;
  /** Dynamic import of the guard's pure-function module — mirrors D2's `() => Promise<GuardModule>`. */
  module: () => Promise<GuardModule>;
  /** Per-guard budget (ms) within the dispatcher's overall process budget. */
  timeoutMs: number;
  /**
   * Logical calibration-log name (D4) — e.g. `"causal-premise"` maps to
   * `.minsky/causal-premise-calibration.jsonl`, preserving the exact
   * filenames `CALIBRATION_LOG_REGISTRY`
   * (`src/domain/calibration/calibration-sweep.ts`) already expects. Omit
   * for guards that never log calibration records.
   *
   * A LIST when one guard writes more than one log (mt#3519). The join the
   * coverage-receipt check builds has always been many-to-many on the read
   * side — `operator-deferral` and `retrospective-trigger` are each written by
   * two guards — but the declaration side could only express one log per
   * guard, so a guard writing two had no way to declare the second. The
   * execution-evidence merge gate is the case: it writes
   * `execution-evidence-at-coverage` itself and `execution-evidence-test-first`
   * through `test-first-evidence.ts`, which it calls in-process.
   *
   * When it IS a list, the FIRST entry is the primary log — the one the
   * dispatcher writes this guard's `outcome.calibration` record to. The rest
   * name logs the guard writes itself; they are declared so the
   * coverage-receipt join can find the guard's invocation evidence, not so the
   * dispatcher can write to them (writing one record to N logs would inflate
   * every downstream fire count).
   *
   * The list type is NON-EMPTY by construction (PR #2543 R1). `[]` is truthy,
   * so a plain `string[]` let an empty declaration pass every `if
   * (reg.calibrationLog)` check and then write nothing — a guard silently
   * logging no calibration records at all, which is the exact failure class
   * this task exists to make visible. Registrations are hand-authored, so the
   * empty state must not be representable.
   */
  calibrationLog?: string | [string, ...string[]];
  /** Whether this guard participates in first-deny-wins short-circuiting (D1). */
  denyCapable: boolean;
  /**
   * Tuning-ownership class (mt#3518; mem#802; beyond-Minsky RFC amendment
   * 2026-08-01 §3). Names WHO may move this guard's thresholds and through
   * WHAT surface — the registration-schema sibling of `attentionCost`
   * (mt#2597) and `contextPriority` (mt#3394):
   *
   * - `"invariant"` — safety/correctness-relevant. Vendor-fixed: changes only
   *   via a code change in this repo; never auto-relaxed by local dismissal
   *   behavior, never locally configurable.
   * - `"preference"` — encodes a workflow-style choice (report length,
   *   heartbeat cadence). The shipped constant is the vendor default; local
   *   override via a registered `MINSKY_*` env var (see `readPositiveIntEnv`
   *   in `types.ts`). Customer-facing tuning questions, where they exist,
   *   are phrased as preference consent — never flip/tune/keep review.
   * - `"advisory"` — calibration-first detectors and informational
   *   injections. Freely adjustable/mutable locally (ack/skip vars);
   *   flip/tune/keep disposition stays vendor-side, fed by the calibration
   *   stream.
   *
   * Typed optional so an unrated guard fails soft at runtime, but
   * `registry.test.ts` requires every entry to carry it — new guards are
   * stamped at birth.
   */
  tuningOwnership?: "invariant" | "preference" | "advisory";
  /**
   * Ordering weight for this guard's `additionalContext` fragment within the
   * dispatcher's MERGED output block (mt#3394). Higher survives first.
   *
   * This orders the OUTPUT only — it does NOT reorder evaluation. Guards are
   * still evaluated in registry order, because first-deny-wins
   * short-circuiting depends on that order and must not shift.
   *
   * Omit for the common case. Fragments at equal priority keep registry order,
   * so an unannotated registry emits exactly the block it emits today. Populate
   * it only where dropping a fragment would cost something specific, and say
   * what in a comment at the registration.
   *
   * Applies to `additionalContext` ONLY (PR #2476 R1). It has no effect on
   * `sessionTitle`, which is a scalar the dispatcher last-write-wins rather
   * than a merged list — there is nothing to order or budget there, so a
   * priority on a title-emitting guard is inert by design, not by oversight.
   *
   * @see composeAdditionalContext in dispatcher.ts — where this is applied.
   */
  contextPriority?: number;
  /**
   * Whether the dispatcher should resolve+parse transcripts before invoking
   * this guard (D6). Guards that don't read transcripts should omit this —
   * the dispatcher still resolves `hostCapSec`/`budgets` unconditionally for
   * every matched guard, but transcript resolution is comparatively more
   * expensive (fs reads across every candidate) and is worth gating.
   */
  needsTranscript?: boolean;
  /**
   * Static attention-cost annotation (mt#2597, evaluation-loop RFC Part 1).
   * Per the RFC: "Attention cost is annotated, not measured... a static
   * per-guard annotation derived from the guard's denial-message size and
   * option count — a registry field, not a per-fire measurement." Latency
   * (the fire-log's `durationMs`) is the LESSER cost dimension; this field
   * captures the vivid cost — reading a denial message, choosing among its
   * remediation options, writing an override rationale.
   *
   * Optional and NOT populated for every guard as of this Phase-1 landing —
   * see `docs/architecture/evaluation-loop-fire-log.md`'s "Known gaps"
   * section. A follow-up sweep should populate this for the remaining
   * guards; the field exists now so that sweep has a documented shape to
   * fill in.
   */
  attentionCost?: {
    /**
     * Character-length CEILING for the guard's rendered denial/warning body —
     * enforced, not descriptive (mt#3479). `guard-feedback-shape.test.ts` runs
     * each guard's canary and fails if the real output exceeds this number, so a
     * guard whose text grows past its declared cost is caught at test time.
     *
     * Until mt#3479 nothing compared these to reality and 14 of 26 had drifted
     * below actual output — `inject-dispatch-watchdog` declared 450 against a
     * measured 1668. That mattered beyond bookkeeping: `dispatcher.ts`'s
     * `MERGED_CONTEXT_BUDGET_CHARS` is DERIVED from these numbers, so the
     * understatement made the merged budget too small and it silently dropped
     * reminders on ordinary turns. Raising a value here widens that budget —
     * treat an increase as a real cost, and prefer trimming the text.
     *
     * For a guard whose output scales with its input (dispatch-watchdog per
     * in-flight dispatch, guard-health per unhealthy guard, memory-search per
     * retrieved record) this is a ratchet against drift measured from ONE canary
     * sample, not a worst-case bound.
     */
    denialMessageSizeChars: number;
    /** Number of distinct remediation options the guard's message presents (e.g. "override X, or do Y, or do Z" = 3). */
    optionCount: number;
  };
  /**
   * Canary declaration (mt#2889, evaluation-loop Phase 1 completion) — the
   * RFC's load-bearing broken-vs-dormant disambiguator. A guard with a
   * declared canary can be run through a SYNTHETIC input known to trigger a
   * specific outcome; a guard that stops firing on its own canary is BROKEN,
   * not merely dormant (low real-world trigger frequency). Without this,
   * mt#2057's dead retrospective-trigger hook (9 days silent) and mt#2835's
   * dead UserPromptSubmit dispatcher (7 days silent, killed by a sibling
   * guard's ungated `main()`) were both indistinguishable from "nobody
   * happened to trip this guard yet" until an operator noticed by hand.
   *
   * `input` is a `ClaudeHookInput`/`ToolHookInput` FRAGMENT — only the fields
   * this specific guard's `run()` actually reads need to be populated (the
   * canary runner, `scripts/run-guard-canaries.ts`, merges it onto a minimal
   * base input). `transcriptLines` is populated directly (bypassing a real
   * `transcript_path` file read) for `needsTranscript` guards — synthetic
   * `TranscriptLine[]` content, reusing phrases already present in the
   * guard's own source or `.test.ts` fixtures per this task's instruction
   * ("existing unit-test fixtures qualify as canary inputs — reuse them, do
   * not invent new ones").
   *
   * `expects` names which `GuardOutcome` field the canary input should
   * populate on a HEALTHY guard: `"deny"` (outcome.deny set), `"warn"`
   * (outcome.additionalContext set — the RFC's fire-log `"warn"` decision),
   * `"calibration"` (outcome.calibration set — a calibration-first detector
   * like `causal-premise-detector` with `INJECTION_ENABLED=false`), or
   * `"sessionTitle"` (outcome.sessionTitle set — `auto-session-title`'s
   * scalar-output shape).
   */
  canary?: GuardCanary;

  /**
   * A SECOND canary posed at the guard's WORST CASE, for guards whose feedback
   * length scales with their input (mt#3705).
   *
   * `canary` above is a single fixed sample, so for a guard that renders one
   * line per matched item — or interpolates a value with no length bound of its
   * own, like a caught `Error.message` — measuring it establishes the FLOOR of
   * the rendered size, not the ceiling. `guard-feedback-shape.test.ts` checks
   * `attentionCost.denialMessageSizeChars` against whatever it can render, so
   * for those guards the annotation was only ever a ratchet against drift; its
   * own header said so and named three examples. That was mt#3479's documented,
   * deliberate deferral, taken without a magnitude estimate. The estimate turned
   * out to be 2.7x (`guard-health-escalation-detector`: declared 600, rendered
   * 1649 at six failing guards), which is what promoted the deferral to work.
   *
   * Declare this on any guard classified GROWTH-SHAPED — either axis: an
   * uncapped iteration over a runtime-length collection, or an unbounded
   * interpolated value. Pose it at the largest input the guard can actually
   * face, not a comfortable one; the point is to make the annotation a true
   * ceiling rather than a sample. A guard that CAPS its own output (the
   * `…and N more` pattern) is bounded by construction and needs no second
   * canary — capping is the preferred fix, since the ceiling exists to be
   * spent against rather than raised.
   *
   * Same shape as `canary` so the runner treats them identically; the shape
   * test renders BOTH and enforces the ceiling against the larger.
   */
  worstCaseCanary?: GuardCanary;
}

/**
 * A canary declaration — a synthetic input plus the outcome kind a healthy
 * guard should produce from it.
 *
 * Extracted to a named type (mt#3705) so `canary` and `worstCaseCanary` are
 * the same shape by construction rather than by two copies kept in sync.
 */
export interface GuardCanary {
  input: Partial<ClaudeHookInput> & Record<string, unknown>;
  transcriptLines?: TranscriptLine[];
  expects: "deny" | "warn" | "calibration" | "sessionTitle";
  /**
   * Optional pre-invocation priming hook for STATEFUL guards whose real
   * outcome depends on a prior invocation (e.g. `skill-staleness-detector`
   * only warns on its SECOND call for a given session — the first
   * establishes a baseline). Receives the SAME dynamically-imported guard
   * module and synthetic `DispatchContext` the real canary check will use,
   * so it can call `mod.run()` itself as many times as needed to prime
   * state before the canary runner's own (checked) invocation. May
   * optionally RETURN a partial input patch (e.g. a dynamically-generated
   * temp `cwd`/`session_id` the checked invocation must reuse) — merged
   * onto `canary.input` after `setup` completes, so the checked call sees
   * whatever state `setup` just primed. Most guards don't need this — omit
   * for anything whose outcome is determined by a single `run()` call.
   */
  setup?: (
    mod: GuardModule,
    ctx: DispatchContext
  ) => Record<string, unknown> | void | Promise<Record<string, unknown> | void>;
}

